$tools = @(
  'git',
  'node',
  'npm',
  'python',
  'java',
  'adb',
  'aiot'
)

$rows = foreach ($tool in $tools) {
  $cmd = Get-Command $tool -ErrorAction SilentlyContinue
  if ($cmd) {
    $version = ''
    try {
      if ($tool -eq 'java') {
        $version = (& $tool -version 2>&1 | Select-Object -First 1)
      } else {
        $version = (& $tool --version 2>&1 | Select-Object -First 1)
      }
    } catch {
      $version = $_.Exception.Message
    }
    [pscustomobject]@{
      Tool = $tool
      Status = 'OK'
      Path = $cmd.Source
      Version = $version
    }
  } else {
    [pscustomobject]@{
      Tool = $tool
      Status = 'Missing'
      Path = ''
      Version = ''
    }
  }
}

$rows | Format-Table -AutoSize

