export default {
  private: {
    selectedCategory: 'mixed',
    goalText: '今天下午要写比赛代码，晚上想运动，但压力有点高，只有3小时',
    heartRate: 76,
    spo2: 97,
    stress: 20,
    completed: 0,
    reviewText: '等待执行反馈',
    recording: false,
    voiceBusy: false,
    voiceStatus: '录音将发送至小米 MiMo 云端',
    aiBusy: false,
    aiStatus: '本地规则已就绪',
    plan: planner.createPlan({
      category: 'mixed',
      text: '今天下午要写比赛代码，晚上想运动，但压力有点高，只有3小时',
      vitals: { heartRate: 76, spo2: 97, stress: 20 },
    }),
  },

  onInit() {
    this._destroyed = false;
    this._voiceId = 0;
    this._aiId = 0;
  },

  onReady() {
    this.refreshHealth();
    this.subscribeHealth();
  },

  onDestroy() {
    this._destroyed = true;
    this.cancelVoice();
    this.invalidateAi();
    ALL.forEach((type) => unsubscribe(type));
  },

  setDaily() {
    this.invalidateAi();
    this.selectedCategory = 'daily';
  },
  setStudy() {
    this.invalidateAi();
    this.selectedCategory = 'study';
  },
  setFitness() {
    this.invalidateAi();
    this.selectedCategory = 'fitness';
  },
  setMixed() {
    this.invalidateAi();
    this.selectedCategory = 'mixed';
  },
  onGoalChange(event) {
    if (!event || typeof event.value !== 'string' || event.value === this.goalText) return;
    this.cancelVoice();
    this.invalidateAi();
    this.goalText = event.value;
  },
  fillDemo() {
    this.cancelVoice();
    this.invalidateAi();
    this.goalText = '今天下午要写比赛代码，晚上想运动，但压力有点高，只有3小时';
    this.selectedCategory = 'mixed';
  },
  toggleVoice() {
    if (this.recording) {
      this.recording = false;
      this.voiceStatus = '正在结束录音';
      try { stopRecording(); } catch (error) {
        this.cancelVoice();
        this.voiceStatus = '停止录音失败，请重试';
      }
      return;
    }
    if (this.voiceBusy || this.aiBusy || this._destroyed) return;
    const id = ++this._voiceId;
    const current = () => !this._destroyed && id === this._voiceId;
    this.voiceBusy = true;
    this.recording = true;
    this.voiceStatus = '录音中，最长 8 秒';
    this._recordTimer = setTimeout(() => {
      if (!current()) return;
      this.cancelVoice();
      this.voiceStatus = '录音未返回，请检查麦克风';
    }, 12000);
    try {
      startRecording(
        (data) => {
          const uri = data && data.uri;
          if (!current()) { discardRecording(uri); return; }
          clearTimeout(this._recordTimer);
          this.recording = false;
          if (!uri) {
            this.cancelVoice();
            this.voiceStatus = '录音文件不可用，请重试';
            return;
          }
          this.voiceStatus = 'MiMo 正在转写';
          this._voiceTask = transcribeRecording(uri);
          this._voiceTask.promise.then((text) => {
            if (!current()) return;
            this._voiceTask = null;
            this.voiceBusy = false;
            this.goalText = text;
            this.voiceStatus = '转写完成，待确认目标';
          }, (error) => {
            if (!current()) return;
            this._voiceTask = null;
            this.voiceBusy = false;
            this.voiceStatus = transcription.MESSAGES[error && error.code] || '转写失败，原目标已保留';
          });
        },
        () => {
