  }

  tasks.push(build('study', text.includes('比赛') ? '比赛开发' : '重点任务', compact ? 35 : 50, '先做可提交部分', 8));
  tasks.push(build('rest', '短休息', 8, '喝水活动一下', 5));
  tasks.push(build('study', '补齐文档', compact ? 20 : 35, '同步记录思路', 8));

