<script>
import planner from './planner.js';
import { getRecent, subscribe, unsubscribe, DATA_TYPES } from './health.js';
import { startRecording, stopRecording, transcribeRecording, discardRecording } from './voice.js';
import transcription from './transcription.js';
import velaclaw from '@system.velaclaw';

const ALL = [DATA_TYPES.HEART_RATE, DATA_TYPES.SPO2, DATA_TYPES.STRESS];

export default {
  private: {
    selectedCategory: 'mixed',
    goalText: '今天下午要写比赛代码，晚上想运动，但压力有点高，只有3小时',
    heartRate: 76,
    spo2: 97,
    stress: 20,
    completed: 0,
    reviewText: '等待执行反馈',
    recording: false,
    voiceBusy: false,
    voiceStatus: '录音将发送至小米 MiMo 云端',
    aiBusy: false,
    aiStatus: '本地规则已就绪',
    plan: planner.createPlan({
      category: 'mixed',
      text: '今天下午要写比赛代码，晚上想运动，但压力有点高，只有3小时',
      vitals: { heartRate: 76, spo2: 97, stress: 20 },
    }),
  },

  onInit() {
    this._destroyed = false;
    this._voiceId = 0;
    this._aiId = 0;
  },

  onReady() {
    this.refreshHealth();
    this.subscribeHealth();
  },

  onDestroy() {
    this._destroyed = true;
    this.cancelVoice();
    this.invalidateAi();
    ALL.forEach((type) => unsubscribe(type));
  },

  setDaily() {
    this.invalidateAi();
    this.selectedCategory = 'daily';
  },
  setStudy() {
    this.invalidateAi();
    this.selectedCategory = 'study';
  },
  setFitness() {
    this.invalidateAi();
    this.selectedCategory = 'fitness';
  },
  setMixed() {
    this.invalidateAi();
    this.selectedCategory = 'mixed';
  },
  onGoalChange(event) {
    if (!event || typeof event.value !== 'string' || event.value === this.goalText) return;
    this.cancelVoice();
    this.invalidateAi();
    this.goalText = event.value;
  },
  fillDemo() {
    this.cancelVoice();
    this.invalidateAi();
    this.goalText = '今天下午要写比赛代码，晚上想运动，但压力有点高，只有3小时';
    this.selectedCategory = 'mixed';
  },
  toggleVoice() {
    if (this.recording) {
      this.recording = false;
      this.voiceStatus = '正在结束录音';
      try { stopRecording(); } catch (error) {
        this.cancelVoice();
        this.voiceStatus = '停止录音失败，请重试';
      }
      return;
    }
    if (this.voiceBusy || this.aiBusy || this._destroyed) return;
    const id = ++this._voiceId;
    const current = () => !this._destroyed && id === this._voiceId;
    this.voiceBusy = true;
    this.recording = true;
    this.voiceStatus = '录音中，最长 8 秒';
    this._recordTimer = setTimeout(() => {
      if (!current()) return;
      this.cancelVoice();
      this.voiceStatus = '录音未返回，请检查麦克风';
    }, 12000);
    try {
      startRecording(
        (data) => {
          const uri = data && data.uri;
          if (!current()) { discardRecording(uri); return; }
          clearTimeout(this._recordTimer);
          this.recording = false;
          if (!uri) {
            this.cancelVoice();
            this.voiceStatus = '录音文件不可用，请重试';
            return;
          }
          this.voiceStatus = 'MiMo 正在转写';
          this._voiceTask = transcribeRecording(uri);
          this._voiceTask.promise.then((text) => {
            if (!current()) return;
            this._voiceTask = null;
            this.voiceBusy = false;
            this.goalText = text;
            this.voiceStatus = '转写完成，待确认目标';
          }, (error) => {
            if (!current()) return;
            this._voiceTask = null;
            this.voiceBusy = false;
            this.voiceStatus = transcription.MESSAGES[error && error.code] || '转写失败，原目标已保留';
          });
        },
        () => {
          if (!current()) return;
          this.cancelVoice();
          this.voiceStatus = '录音不可用，请检查麦克风';
        },
      );
    } catch (error) {
      this.cancelVoice();
      this.voiceStatus = '当前设备不支持录音';
    }
  },
  cancelVoice() {
    this._voiceId++;
    clearTimeout(this._recordTimer);
    if (this._voiceTask) {
      this._voiceTask.cancel();
      this._voiceTask = null;
    }
    const wasRecording = this.recording;
    this.recording = false;
    if (this.voiceBusy) this.voiceStatus = '语音输入已取消';
    this.voiceBusy = false;
    if (wasRecording) {
      try { stopRecording(); } catch (error) { /* Device may already be stopped. */ }
    }
  },
  invalidateAi() {
    this._aiId++;
    clearTimeout(this._aiTimer);
    if (this.aiBusy) this.aiStatus = '目标已变化，待重新生成';
    this.aiBusy = false;
  },
  generatePlan() {
    if (this.voiceBusy || this.aiBusy || this._destroyed) return;
    if (!this.goalText.trim()) {
      this.voiceStatus = '目标不能为空';
      return;
    }
    const payload = {
      category: this.selectedCategory,
      text: this.goalText,
      vitals: {
        heartRate: this.heartRate,
        spo2: this.spo2,
        stress: this.stress,
      },
    };
    this.plan = planner.createPlan(payload);
    this.completed = 0;
    this.reviewText = '计划已生成，开始执行吧';
    const id = ++this._aiId;
    const finish = (callback) => {
      if (this._destroyed || id !== this._aiId) return;
      clearTimeout(this._aiTimer);
      this._aiId++;
      this.aiBusy = false;
      callback();
    };
    this.aiBusy = true;
    this.aiStatus = '正在请求 MiMo AI...';
    this._aiTimer = setTimeout(() => finish(() => {
      this.finishAiFallback('AI 请求超时，已使用本地计划');
    }), 30000);
    try {
      velaclaw.ask({
        query: [
          '你是 VelaPlan 腕上计划生成引擎。只输出 JSON，不输出 Markdown。',
          '请按用户类别、目标、时间和健康状态生成短小可执行的一日计划。',
          '每个任务必须包含 time、type、name、duration、tip；不做医疗诊断。',
          JSON.stringify(payload),
        ].join('\n'),
        success: (data) => finish(() => this.applyAiPlan(data)),
        fail: () => finish(() => this.finishAiFallback('AI 暂不可用，已使用本地计划')),
      });
    } catch (error) {
      finish(() => this.finishAiFallback('当前设备未启用 AI，已使用本地计划'));
    }
  },
  applyAiPlan(data) {
    try {
      const aiPlan = planner.parsePlanResponse(data && data.reply);
      this.plan = Object.assign({}, this.plan, aiPlan, {
        category: this.selectedCategory,
        vitals: {
          heartRate: this.heartRate,
          spo2: this.spo2,
          stress: this.stress,
        },
        source: 'velaclaw',
      });
      this.reviewText = 'AI 计划已生成，开始执行吧';
      this.aiStatus = 'MiMo AI 已生成计划';
    } catch (error) {
      this.finishAiFallback('AI 返回格式不可用，已使用本地计划');
    }
  },
  finishAiFallback(message) {
    this.aiStatus = message;
    this.reviewText = '计划已生成，开始执行吧';
  },
  finishOne() {
    const total = this.plan.tasks.length || 1;
    const nextPlan = planner.completeNextTask(this.plan);
    if (nextPlan !== this.plan) {
      this.plan = nextPlan;
      this.completed = Math.min(total, this.completed + 1);
    }
    this.reviewText = `已完成 ${this.completed}/${total}，${this.plan.nextAdvice}`;
  },
  refreshHealth() {
    getRecent(ALL).then((list) => list.forEach((sample) => this.applySample(sample)));
  },
  subscribeHealth() {
    ALL.forEach((type) => {
      subscribe(type, (sample) => this.applySample(sample));
    });
  },
  applySample(sample) {
    if (!sample || !sample.ok) {
      return;
    }
    if (sample.dataType === DATA_TYPES.HEART_RATE) {
      this.heartRate = sample.value;
    } else if (sample.dataType === DATA_TYPES.SPO2) {
      this.spo2 = sample.value;
    } else if (sample.dataType === DATA_TYPES.STRESS) {
      this.stress = sample.value;
    }
  },
};
</script>

