  f = fixture();
  f.page.toggleVoice();
  f.recorded({});
  assert.strictEqual(f.page.voiceBusy, false, 'missing recording URI must unlock the page');
  assert.strictEqual(f.calls.uploads.length, 0);
  console.log('watch voice page tests passed');
}

