# 演示脚本

## 30 秒介绍

VelaPlan 是一款基于 openvela 的腕上 AI 计划助手。用户只需说出目标，选择计划周期并标记重要事项，系统结合佩戴时的健康状态和天气场景生成可执行计划，在手表端完成提醒、打卡、动态调整和复盘。

## 现场演示流程

1. 打开 VelaPlan 首页，展示当前心率、血氧、压力和“健康数据已接入”。
2. 选择“今日”，输入或通过语音说：`今天写代码两小时，晚上散步半小时。` 停止后等待真实转写，展示并检查目标文字。若失败，明确说明失败并改用文字输入，不能把示例当作识别结果。
3. 打开“重要事项”，输入提醒时间 `18:00`，把天气切换为“下雨”，点击“生成计划”。
4. 展示 MiMo AI 返回或本地规则兜底的任务列表，以及“下雨，已调整运动安排”和应用内提醒状态。
5. 点击“完成一项”或“继续执行”，展示任务变绿和完成数量更新；点击“延期到明天”，展示任务仍保留且延期原因可见。
6. 在健康 Mock 中把压力调高或心率调高，重新生成计划，展示呼吸放松、低强度活动等调整，并说明这是相对个人基线的非医疗建议。
7. 切换到“本周”展示七天任务，再重新打开页面，展示本地计划已恢复；最后展示复盘和次日建议。

## 讲解重点

- 不是普通待办清单，而是结合腕上健康状态和天气动态调整计划。
- 初赛使用官方手表模拟器和 `service.health` Mock 数据。
- 端侧负责轻交互、录音和健康数据读取，`@system.velaclaw` 负责调用设备端 AI Agent；没有 AI 配置时由本地规则保障演示。
- 项目可扩展到真实手表、手环和更多场景。
- 天气为内置演示场景，提醒为应用内提醒；没有验证系统闹钟 API，不把它宣传为系统级闹钟。

let period = 'today';
let weather = 'clear';
let currentPlan = null;
const goal = document.querySelector('#goal');
const tasks = document.querySelector('#tasks');
const title = document.querySelector('#title');
const summary = document.querySelector('#summary');
const context = document.querySelector('#context');
const reminder = document.querySelector('#reminder');
const hr = document.querySelector('#hr');
const spo2 = document.querySelector('#spo2');
const stress = document.querySelector('#stress');

function vitals() {
  return {
    heartRate: Number(hr.textContent),
    spo2: Number(spo2.textContent),
    stress: Number(stress.textContent),
  };
}

async function generate() {
  const response = await fetch('/api/plan', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      text: goal.value,
      period,
      important: document.querySelector('#important').checked,
      reminderTime: document.querySelector('#reminderTime').value,
      weather,
      mood: document.querySelector('#moodLow').checked ? 'low' : 'normal',
      vitals: vitals(),
    }),
  });
  const plan = await response.json();
  currentPlan = plan;
  generateView(plan);
}

document.querySelectorAll('[data-period]').forEach((button) => {
  button.addEventListener('click', () => {
    document.querySelectorAll('[data-period]').forEach((item) => item.classList.remove('active'));
    button.classList.add('active');
    period = button.dataset.period;
    generate();
  });
});

document.querySelectorAll('[data-weather]').forEach((button) => {
  button.addEventListener('click', () => {
    document.querySelectorAll('[data-weather]').forEach((item) => item.classList.remove('active'));
    button.classList.add('active');
    weather = button.dataset.weather;
    generate();
  });
});

document.querySelector('#generate').addEventListener('click', generate);

document.querySelector('#finish').addEventListener('click', () => {
  if (!currentPlan) return;
  const task = currentPlan.tasks.find((item) => item.status !== 'done');
  if (!task) return;
  task.status = 'done';
  generateView(currentPlan);
});

function generateView(plan) {
  title.textContent = plan.title;
  summary.textContent = plan.summary;
  context.textContent = plan.context || '';
  reminder.textContent = plan.important ? `应用内提醒：${plan.reminderTime}` : '未设置重要事项提醒';
  tasks.innerHTML = plan.tasks.map((task) => `
    <article class="task ${task.status === 'done' ? 'done' : ''}">
      <time>${task.time}</time>
      <div><strong>${task.name}</strong><span>${task.duration} 分钟 · ${task.tip}</span><small>${task.adjustmentReason || ''}</small></div>
    </article>`).join('');
}

[
  ['#hrRange', hr],
  ['#spo2Range', spo2],
  ['#stressRange', stress],
].forEach(([selector, target]) => {
  document.querySelector(selector).addEventListener('input', (event) => {
    target.textContent = event.target.value;
    generate();
  });
});

generate();

